@Injectable()
export class ResourceManagementService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(ResourceManagementService.name);

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async fetchResourceByPlant(plant: number): Promise<Array<string>> {
    try {
      const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
      const serviceMethod = `resource/${plant}`;
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );
      if (response) {
        return response as Array<string>;
      }
