import {
  authenticateUser,
  authorizeUser,
  AuthConfigService,
  ApiService,
  extractGroupNames,
  UserAttributesManager,
} from '@mesx/common-ui-lib';
import { User, WebStorageStateStore } from 'oidc-client';
import { defineStore } from 'pinia';
