/**
 * Returns the default configuration for downtime table columns.
 *
 * Each column definition includes details like the label, field accessor,
 * visibility, sortability, and optional styling or formatting logic.
 * @returns Array of column definitions for a downtime table.
 */
function getDefaultDowntimeColumns(): Array<TableColumn> {
  return [
    {
      field: 'shiftCode',
      index: 0,
      label: 'Shift',
      name: 'shift',
      sortable: true,
      visible: true,
    },
    {
      align: 'center',
      field: (row: TableRow): string =>
        row.startDate
          ? DateTime.fromJSDate(new Date(row.startDate), {
              zone: getTimezone(),
            }).toFormat('yyyy-MM-dd HH:mm:ss')
          : '',
      index: 1,
      label: 'Start Datetime',
      name: 'startDatetime',
      sortable: true,
      visible: true,
    },
    {
      align: 'center',
      field: (row: TableRow): string =>
        row.endDate
          ? DateTime.fromJSDate(new Date(row.endDate), {
              zone: getTimezone(),
            }).toFormat('yyyy-MM-dd HH:mm:ss')
          : '',
      index: 2,
      label: 'End Datetime',
      name: 'endDatetime',
      sortable: true,
      visible: true,
    },
    {
      field: (row: TableRow): string => {
        if (!row.duration) return '';
        const totalSeconds = Number.parseInt(row.duration, 10);
        const hours = Math.floor(totalSeconds / 3600)
          .toString()
          .padStart(2, '0');
        const minutes = Math.floor((totalSeconds % 3600) / 60)
          .toString()
          .padStart(2, '0');
        const seconds = (totalSeconds % 60).toString().padStart(2, '0');
        return `${hours}:${minutes}:${seconds}`;
      },
      index: 3,
      label: 'Duration',
      name: 'duration',
      sortable: true,
      visible: true,
    },
    {
      field: 'causeDesc',
      index: 4,
      label: 'Cause',
      name: 'cause',
      sortable: true,
      style: (row: TableRow): string => {
        if (row.cause === 1) {
          return 'background-color: #ba8be3;color: white;';
        }
        if (row.cause === 2) {
          return 'background-color: #5e5e5e;color: white;';
        }
        if (row.cause === 3) {
          return 'background-color: #3dcaf2;color: white;';
