  const response = await axios.post(
    `${downtimeApiBackendBaseUrl}/picture-upload/uploadpicture/?newName=${encodeURIComponent(newName)}`,
    formData,
    {
      headers: {
        'Content-Type': 'multipart/form-data',
        Authorization: `Bearer ${token}`,
      },
    },
  );
  return response.data;
};

