import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class UrlApiConfigService implements OnModuleInit {
  private readonly logger: AppLogger = new AppLogger(UrlApiConfigService.name);

  public constructor(private readonly configService: ConfigService) {}

  public get urlApi(): string {
    return (
      this.configService.get<string>('urlApi') ??
      'https://mesx-ppr.app.corp/epb-be/'
    );
  }

  public get umeApiAppId(): string {
    return this.configService.get<string>('umeApiAppId') ?? '';
  }

  public get plantHryApiAppId(): string {
    return this.configService.get<string>('plantHryApiAppId') ?? '';
  }

  public get masterApiAppId(): string {
    return this.configService.get<string>('masterApiAppId') ?? '';
  }

  public get resourceApiAppId(): string {
    return this.configService.get<string>('resourceApiAppId') ?? '';
  }

  public get productionApiAppId(): string {
    return this.configService.get<string>('productionApiAppId') ?? '';
  }

  public get orderApiAppId(): string {
    return this.configService.get<string>('orderApiAppId') ?? '';
  }

  public get qualityApiAppId(): string {
    return this.configService.get<string>('qualityApiAppId') ?? '';
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'plantHryApiAppId', value: this.plantHryApiAppId },
      { key: 'umeApiAppId', value: this.umeApiAppId },
      { key: 'masterApiAppId', value: this.masterApiAppId },
      { key: 'resourceApiAppId', value: this.resourceApiAppId },
      { key: 'productionApiAppId', value: this.productionApiAppId },
      { key: 'orderApiAppId', value: this.orderApiAppId },
      { key: 'qualityApiAppId', value: this.qualityApiAppId },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.logger.log('All required API Manager configurations are properly set');
  }
}

