export const getAlertCountsForResources = async (
  dto: GetAlertCountsForResourcesDto,
): Promise<Array<AlertCountsByWorkcenterResponseDto>> => {
  const headers: Record<string, string> = {};
  if (token) {
    headers.authorization = `Bearer ${token}`;
  }

  const response: AxiosResponse<Array<AlertCountsByWorkcenterResponseDto>> =
