): { scrapCount: Ref<number | undefined> } {
  const scrapCount = ref<number | undefined>(undefined);
  let intervalId: ReturnType<typeof setInterval> | undefined;

  const fetchScrapCount = async (): Promise<void> => {
    const { plant, workcenter, resource } = hierarchyStore;
