@Injectable()
export class OrderService {
  private readonly daprClient: DaprClient;

  private readonly logger = new AppLogger();

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async getPlantConfigOrder(
    plantId: number,
  ): Promise<PlantResponse | null> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `plant-config-order/${plantId}`;
    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );
      if (response) {
        return response as PlantResponse;
      }
      return null;
    } catch {
      return null;
    }
  }

  public async getCombinedPlantConfig(
    plantId: number,
  ): Promise<CombinedPlantConfigResponse | null> {
    try {
      const plantConfigOrder = await this.getPlantConfigOrder(plantId);

      if (plantConfigOrder) {
        return {
          aggrTimeLvlBoard: plantConfigOrder.aggrTimeLvlBoard,
          offsetFrom: plantConfigOrder.offsetFrom,
          offsetTo: plantConfigOrder.offsetTo,
          toleranceValueWk: plantConfigOrder.toleranceValueWk,
        };
      }

      return null;
    } catch (error) {
      console.warn(error);
      return null;
    }
  }

  public async getGhostByWorkcenterDto(
    plant: number,
    workcenters: Array<string>,
  ): Promise<Record<string, string> | undefined> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `production-order/getGhostByWorkcenters`;
    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.POST,
        {
          plant,
          workcenters,
        },
      );

      if (response) {
        return response as Record<string, string>;
      }
      return undefined;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve Ghost  for plantId ${plant}`,
        error,
      );
      return undefined;
    }
  }
}

