  public async getWorkcenterDetailsById(
    plantId: number,
    workcenterId: string,
  ): Promise<WorkcenterDetailsDto> {
    try {
      const response = await this.daprClient.invoker.invoke(
        this.daprConfigService.plantHierarchyApiAppId,
        `workcenter/GetWorkcenterDetailsById/${plantId}/${workcenterId}`,
        HttpMethod.GET,
      );
      this.logger.log(
        `Fetched workcenter details for ${workcenterId} (plant ${plantId})`,
      );
      return response as WorkcenterDetailsDto;
    } catch (error) {
      this.logger.error(
        `Failed to fetch workcenter details for ${workcenterId} (plant ${plantId})`,
        error,
      );
      throw new InternalServerErrorException(
        'Error fetching workcenter details',
      );
    }
  }
}

