  public get pathToExcludeFromAuth(): Array<string> {
    const raw = this.configService.get<string>('pathToExcludeFromAuth') ?? '';
    return raw.split(';').map((p) => p.trim());
  }

  public async cookieExpirationSeconds(): Promise<number> {
    const value = this.configService.get<string>('cookieExpirationSeconds');
    if (!value) {
      const refreshToken = await this.appConfigService.getConfigurationValue(
        'AUTH_PROXY_COOKIE_EXPIRATION_SECONDS',
      );
      return refreshToken ? Number.parseInt(refreshToken, 10) : 3600;
    }
    return value ? Number.parseInt(value, 10) : 3600;
  }

  public async getTokenRefreshIntervalSeconds(): Promise<number> {
    const value = this.configService.get<string>('tokenRefreshIntervalSeconds');
    if (!value) {
      const refreshToken = await this.appConfigService.getConfigurationValue(
        'AUTH_PROXY_TOKEN_REFRESH_INTERVAL_SECONDS',
      );
      return refreshToken ? Number.parseInt(refreshToken, 10) : 3600;
    }
    return value ? Number.parseInt(value, 10) : 3600;
