import { Module } from '@nestjs/common';
import { CqrsModule } from '@nestjs/cqrs';
import { TypeOrmModule } from '@nestjs/typeorm';
import { BufferController } from '@/modules/order-management/buffer/buffer.controller';
import { Buffer } from '@/modules/order-management/buffer/buffer.entity';

import { CreateBufferHandler } from '@/modules/order-management/buffer/commands/handlers/create-buffer.handler';
import { DeleteBufferHandler } from '@/modules/order-management/buffer/commands/handlers/delete-buffer.handler';
import { UpdateBufferHandler } from '@/modules/order-management/buffer/commands/handlers/update-buffer.handler';
import { FindWksByPlantAndWorkcenterHandler } from '@/modules/order-management/buffer/queries/handlers/find-wk-by-plant-and-workcenter.handler';

import { GetBufferHandler } from '@/modules/order-management/buffer/queries/handlers/get-buffer.handler';

const commandHandlers = [
  CreateBufferHandler,
  UpdateBufferHandler,
  DeleteBufferHandler,
];

const queryHandlers = [GetBufferHandler, FindWksByPlantAndWorkcenterHandler];

@Module({
  imports: [TypeOrmModule.forFeature([Buffer]), CqrsModule],
  controllers: [BufferController],
  providers: [...commandHandlers, ...queryHandlers],
})
export class BufferModule {}

import { CreateBufferDto } from '@/modules/order-management/buffer/dtos/create-buffer.dto';

export class CreateBufferCommand {
  public constructor(public readonly dto: CreateBufferDto) {}
}

export class DeleteBufferCommand {
  public constructor(
    public readonly plant: number,
    public readonly id: number,
  ) {}
}

import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buffer } from '@/modules/order-management/buffer/buffer.entity';
import { CreateBufferCommand } from '@/modules/order-management/buffer/commands/create-buffer.command';

@CommandHandler(CreateBufferCommand)
export class CreateBufferHandler
  implements ICommandHandler<CreateBufferCommand>
{
  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepo: Repository<Buffer>,
  ) {}

  public async execute(command: CreateBufferCommand): Promise<Buffer> {
    const { dto } = command;

    const entity = this.bufferRepo.create({
      ...dto,
    });

    return this.bufferRepo.save(entity);
  }
}

import { NotFoundException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buffer } from '@/modules/order-management/buffer/buffer.entity';
import { DeleteBufferCommand } from '@/modules/order-management/buffer/commands/delete-buffer.command';

@CommandHandler(DeleteBufferCommand)
export class DeleteBufferHandler
  implements ICommandHandler<DeleteBufferCommand>
{
  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepo: Repository<Buffer>,
  ) {}

  public async execute(command: DeleteBufferCommand): Promise<Buffer> {
    const { plant, id } = command;

    const entity = await this.bufferRepo.findOne({
      where: { plant, id },
    });

    if (!entity) {
      throw new NotFoundException(
        `Buffer order ${id} at plant ${plant} not found`,
      );
    }

    return this.bufferRepo.remove(entity);
  }
}

import { NotFoundException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buffer } from '@/modules/order-management/buffer/buffer.entity';
import { UpdateBufferCommand } from '@/modules/order-management/buffer/commands/update-buffer.command';

@CommandHandler(UpdateBufferCommand)
export class UpdateBufferHandler
  implements ICommandHandler<UpdateBufferCommand>
{
  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepo: Repository<Buffer>,
  ) {}

  public async execute(command: UpdateBufferCommand): Promise<Buffer> {
    const { plant, id, dto } = command;

    const entity = await this.bufferRepo.findOne({
      where: { plant, id },
    });

    if (!entity) {
      throw new NotFoundException(
        `Buffer order ${id} at plant ${plant} not found`,
      );
    }

    Object.assign(entity, dto);

    return this.bufferRepo.save(entity);
  }
}

