  IsInt,
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsPositive,
  IsString,
  MaxLength,
} from 'class-validator';

export class CreateBufferDto {
  @ApiProperty({
    description: 'Plant identifier',
    example: 1146,
    required: true,
  })
  @IsInt()
  @IsNotEmpty()
  public plant: number;

  @ApiProperty({
    description: 'Action Type',
    example: 'Creation',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(16)
  public actionType?: string;

  @ApiProperty({
    description: 'Order ID',
    example: 'PO123456',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(36)
  public orderId?: string;

  @ApiProperty({
    description: 'Material number associated with the order',
    example: 'MAT-001',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(18)
  public materialNumber: string;

  @ApiProperty({
    description: 'Upstream Material number associated with the order',
    example: 'UPMAT001',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(18)
  public upstreamMaterial?: string;

  @ApiProperty({
    description: 'Production line where the order will be processed',
    example: 'WC100',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(8)
  public workcenter?: string;

  @ApiProperty({
    description: 'TPA Number',
    example: 'TPA-2025-001',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(1024)
  public tpaNumber?: string;

  @ApiProperty({
    description: 'Delivery Number',
    example: 'OUT20251002',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(50)
  public deliveryNumber?: string;

  @ApiProperty({
    description: 'Start Picking datetime',
    example: '2025-10-02T08:00:00',
    required: false,
  })
  @IsOptional()
  @Type(() => Date)
  @IsDate()
  public startPickingDatetime?: Date;

  @ApiProperty({
    description: 'End Picking datetime',
    example: '2025-10-02T08:00:00',
    required: false,
