export const useMenuStore = defineStore('menu', () => {
  const menuItems = ref<Array<MenuList>>([]);

  const fetchMenuItems = async (): Promise<Array<MenuList>> => {
    if (menuItems.value.length === 0) {
      try {
        menuItems.value = await getMenuItems();
        return menuItems.value;
      } catch (error) {
        console.error(error);
        return [];
      }
    }
    return menuItems.value;
  };

  return {
    fetchMenuItems,
    menuItems,
  };
});

