    // Action to fetch picking order data
    async fetchPickingOrderData(_isAlert?: string): Promise<Array<TableRow>> {
      const pickingTableStore = usePickingTableStore();
      const screenName = _isAlert ? 'alert' : 'picking';
      const urlParameters = new URLSearchParams(window.location.search);
      const workcenterParameter = urlParameters.get('workcenter');
      const plantParameter = urlParameters.get('plant');
      const alertLevelParameter = urlParameters.get('alertLevel');
      const workcenterId = sessionStorage.getItem('workcenterId');
      if (workcenterId) {
        this.workCentersSelected = [workcenterId];
      }
      if (workcenterParameter && plantParameter) {
        // â Only take workcenter & plant, ignore other filters
        this.workCentersSelected = [workcenterParameter];
        switch (alertLevelParameter) {
          case 'O': {
            this.alertLevel = 'ORANGE';

            break;
          }
          case 'Y': {
            this.alertLevel = 'YELLOW';

            break;
          }
          case 'R': {
            this.alertLevel = 'RED';

            break;
          }
          default: {
            this.alertLevel = '';
          }
        }
        await this.filterByCriteria(_isAlert ? 'alert' : '501');
      } else {
        const filterSelections = await api.getFiltersSelections(screenName);
        this.workcenterList = filterSelections.workcenter;
        this.sfgWorkcenterList = filterSelections.sfgWorkcenter;
        this.srcLocList = filterSelections.sourceLocation;
        this.destLocList = filterSelections.destinationLocation;
        this.tpaCodeList = filterSelections.tpaCode;
        this.huCurStrLocList = filterSelections.huCurrentStorageLocation;
        this.huCurStrLocListAlert = filterSelections.huCurrentStorageLocation;
        this.workcenterListAlert = filterSelections.workcenter;
        this.sourceLocListAlert = filterSelections.sourceLocation;
        this.destLocListAlert = filterSelections.destinationLocation;
        this.tpaCodeListAlert = filterSelections.tpaCode;
        this.customerList = filterSelections.customer;
        this.outboundList = filterSelections.outbound;
        this.tpaNumList = filterSelections.tpaNumber;
        await (_isAlert
          ? this.filterByCriteria('alert')
          : this.filterByCriteria('501'));
      }
      return Array.isArray(pickingTableStore.pickingFiltredRows)
        ? pickingTableStore.pickingFiltredRows
        : [];
    },
    async filterByCriteria(status: string) {
      let isAlert: boolean;
      this.savedPickingTimeScale = this.pickingTimeScale;
      this.savedPickingTimeMin = this.pickingTimeMin;
      this.savedPickingTimeMax = this.pickingTimeMax;
      const pickingTableStore = usePickingTableStore();
      if (status === '501') {
        isAlert = false;
        // Remove 'CLOSED' custom status for picking screen
        const excludedCustStatuses = new Set(['CLOSED']);
        this.custStatusSelected = this.custStatusSelected.filter(
          (custStatus) => !excludedCustStatuses.has(custStatus),
        );
        const data = await api.searchOrderBycriteria(
          this.workCentersSelected,
          this.sfgWorkCentersSelected,
          this.materialsSelected,
          this.srcLocsSelected,
          this.destLocsSelected,
          this.pickingStatusSelected,
          this.custStatusSelected,
          this.cstr,
          this.otbDlr,
          this.tpaNum,
          this.tpaCodesSelected,
          this.endProdTimeType,
          this.pickingTimeScale,
          this.pickingTimeMax,
          this.pickingTimeMin,
          this.endProdDate,
          this.startPreparationType,
          this.endPreparationType,
          this.truckDepartureType,
          this.startPreparationTime,
          this.endPreparationDate,
          this.truckDepartureDate,
          this.promiseTime,
          this.alert,
          this.rescheduled,
          this.huCurStrLocSelected,
          isAlert,
          status,
          this.alertLevel,
          this.pickingOrderIDSelected,
        );
        pickingTableStore.pickingFiltredRows = Array.isArray(data.shopOrderList)
          ? data.shopOrderList
          : [data.shopOrderList];
        return data.shopOrderList;
      }
      if (status === 'alert') {
        isAlert = true;
        // Remove specific custom statuses
        const excludedCustStatuses = new Set([
          'PIK_CLOSED',
          'PICKED',
          'PALLETIZED',
        ]);
        this.custStatusSelected = this.custStatusSelected.filter(
          (custStatus) => !excludedCustStatuses.has(custStatus),
        );

        // Remove specific picking statuses
        const excludedPickingStatuses = new Set(['CLOSED']);
        this.pickingStatusSelected = this.pickingStatusSelected.filter(
          (custStatus) => !excludedPickingStatuses.has(custStatus),
        );

        const data = await api.searchOrderBycriteria(
          this.workCentersSelected,
          this.sfgWorkCentersSelected,
          this.materialsSelected,
          this.srcLocsSelected,
          this.destLocsSelected,
          this.pickingStatusSelected,
          this.custStatusSelected,
          this.cstr,
          this.otbDlr,
          this.tpaNum,
          this.tpaCodesSelected,
          this.endProdTimeType,
          this.pickingTimeScale,
          this.pickingTimeMax,
          this.pickingTimeMin,
          this.endProdDate,
          this.startPreparationType,
          this.endPreparationType,
          this.truckDepartureType,
          this.startPreparationTime,
          this.endPreparationDate,
          this.truckDepartureDate,
          this.promiseTime,
          this.alert,
          this.rescheduled,
          this.huCurStrLocSelected,
          isAlert,
          undefined,
          this.alertLevel,
        );
        pickingTableStore.alertFiltredRows = Array.isArray(data.shopOrderList)
          ? data.shopOrderList
          : [data.shopOrderList];
        return data.shopOrderList;
      }

      return [];
    },
