        { attribute: `material_${tableName}`, data: this.materialsSelected },
        { attribute: `srcLoc_${tableName}`, data: this.srcLocsSelected },
        { attribute: `destLocs_${tableName}`, data: this.destLocsSelected },
        { attribute: `hustrLoc_${tableName}`, data: this.huCurStrLocSelected },
        {
