          data: [this.pickingTimeMin.toString()],
        },
        {
          attribute: `pickingTimeMax_${tableName}`,
          data: [this.pickingTimeMax.toString()],
        },

        { attribute: `endProdDate_${tableName}`, data: [this.endProdDate] },
        {
          attribute: `startPreparationType_${tableName}`,
          data: [this.startPreparationType],
        },
        {
          attribute: `startPreparationTime_${tableName}`,
          data: [this.startPreparationTime],
        },
        {
