    async getSharedGroupUpdatePayload(
      groupName: string,
      appName: string,
      plant: string,
      tableName: string,
    ): Promise<
      | {
          id: number;
          data: {
            appName: string;
            groupName: string;
            plant: string;
            userCriteria: string;
          };
        }
      | undefined
    > {
      const existingGroup = await getFilterByUserAndGroup(
        plant,
        groupName,
        appName,
      );
      if (!existingGroup?.id) return undefined;

      const attributes = this.getFilterAttributes(tableName);
      const userCriteria = this.convertAttributesToUserCriteria(
        attributes,
        tableName,
      );

      return {
        id: existingGroup.id,
        data: {
          appName,
          groupName,
          plant,
          userCriteria,
        },
      };
    },

    applyFilterConfigToParent(userCriteria: string, tableName: string) {
      const attributes = this.convertUserCriteriaToAttributes(
        userCriteria,
        tableName,
      );

      const setters: Record<string, (data: Array<string>) => void> = {
