import {
  Catch,
  HttpException,
  ArgumentsHost,
  HttpStatus,
} from '@nestjs/common';
import { BaseExceptionFilter } from '@nestjs/core';
import { ExceptionResponse } from './interfaces/exception-response.interface';

@Catch(HttpException)
export class MesGenericErrorFilter extends BaseExceptionFilter {
  public static catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();
    const response = context.getResponse();
    const request = context.getRequest();
    // Determine the status code
    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    let message = 'An error occurred';
    let errorCode = 'UNHANDLED_EXCEPTION';
    if (exception instanceof HttpException) {
      const exceptionResponse = exception.getResponse();
      if (typeof exceptionResponse === 'string') {
        message = exceptionResponse;
      } else if (
        typeof exceptionResponse === 'object' &&
        exceptionResponse !== null
      ) {
        message = (exceptionResponse as ExceptionResponse).message ?? message;
        errorCode = (exceptionResponse as ExceptionResponse).error ?? errorCode;
      }
    } else {
      message = (exception as Error).message || message;
    }

    // Default behavior for other exceptions
    response.status(status).json({
      body: request.body,
      errorCode,
      message,
      params: request.params,
      path: request.url,
      query: request.query,
      statusCode: status,
      timestamp: new Date().toISOString(),
    });
  }
}

import { HourRange } from '../../modules/down-time-ticket/interfaces/date-range.interface';

/**
 * Splits a date range into hourly intervals, creating an array of HourRange objects
 * where each range represents one hour from the start to end time.
 * @param from - The start date and time for the range
 * @param to - The end date and time for the range
 * @returns An array of HourRange objects representing each hour in the given range
 */
export function splitIntoHours(from: Date, to: Date): Array<HourRange> {
  const hours: Array<HourRange> = [];
  const current = new Date(from);
  const endTime = new Date(to);
  endTime.setMinutes(59, 59, 999);

  while (current <= endTime) {
    const start = new Date(current);
    const end = new Date(current);
    end.setMinutes(59, 59, 999);

    hours.push({ start, end });
    current.setHours(current.getHours() + 1, 0, 0, 0);
  }

  return hours;
}

