  logType: string;
  operationName: string;
  runtime: number;
  srcLocation: string;
  waitingMsgCount: number;
}

/**
 * Execution function and log runtime
 * @param logger Application logger
 * @param context Log context
 * @param operation Function to execute
 * @param operationInfo Function properties
 * @param operationInfo.name Function name
 * @param operationInfo.srcLocation Caller code source location
 * @param details (optional)
 * @param startTime starting time
 * @returns function output
 */
export async function execAndLog<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  operationInfo: {
    name: string;
    srcLocation: string;
  },
  details?: Record<string, unknown>,
  startTime = Date.now(),
): Promise<T> {
  const result = await operation();
  const logTrace: LogTrace = {
    details,
    logType: 'Exec trace',
    operationName: operationInfo.name,
    runtime: Date.now() - startTime,
    srcLocation: operationInfo.srcLocation,
    waitingMsgCount: getPendingMessagesCount(),
  };
  logger.debug(JSON.stringify(logTrace), context);
  return result;
}

/**
 * Determines whether the given Redis error requires reauthentication.
 *
 * Checks the error message against a list of known critical Redis connection/authentication errors.
 * @param error - The error thrown by the Redis client.
 * @returns True if the error suggests that reauthentication should be attempted; otherwise, false.
 */
export function shouldReauthenticate(error: Error): boolean {
  const criticalErrors = [
    'WRONGPASS',
    'NOAUTH',
    'invalid username-password',
    'user is disabled',
    'Socket closed unexpectedly',
    'ECONNRESET',
    'Connection lost',
    'Redis connection lost',
  ];

  return criticalErrors.some((message) => error.message.includes(message));
}

