#!/usr/bin/env node
import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import type { NestExpressApplication } from '@nestjs/platform-express';
import * as express from 'express';
import { AppLogger } from './common/logger/app-logger';
import { AppModule } from '@/app.module';

/**
 * Bootstrap function to initialize the application
 */
async function bootstrap(): Promise<void> {
  // Create the HTTP application
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });

  // Initialize logger
  const logger = app.get(AppLogger);
  await logger.init();

  app.use(express.json({ type: 'application/cloudevents+json' }));

  // Global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );

  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });

  // Start HTTP server
  const httpPort = Number(process.env.HTTP_PORT || 3000);
  await app.listen(httpPort);
  logger.log(`HTTP server started on port ${httpPort}`, {
    method: 'bootstrap',
    service: 'main',
  });

  // Handle graceful shutdown
  process.on('SIGINT', async () => {
    logger.log('Received SIGINT, shutting down gracefully...', {
      method: 'shutdown',
      service: 'main',
    });
    await app.close();
    process.exit(0);
  });

  process.on('SIGTERM', async () => {
    logger.log('Received SIGTERM, shutting down gracefully...', {
      method: 'shutdown',
      service: 'main',
    });
    await app.close();
    process.exit(0);
  });
}

bootstrap().catch((error) => {
  console.error('Failed to start application:', error);
  process.exit(1);
});

import { Controller, Get, Header, Req } from '@nestjs/common';
import { Request } from 'express';
import { AppLogger } from '@/common/logger/app-logger';
import { StreamMonitorService } from '@/services/stream-monitor.service';

@Controller('')
export class MetricsController {
  public constructor(
    private readonly streamMonitor: StreamMonitorService,
    private readonly logger: AppLogger,
  ) {}

  // Metrics API endpoint for KEDA
  @Get('metrics/pending-messages')
  @Header('Content-Type', 'application/json')
  public async getPendingMessagesMetric(): Promise<{ metricValue: number }> {
    try {
      // Collect current metrics from Redis
      const metrics = await this.streamMonitor.collectMetrics();

      this.logger.debug('Metrics API called', {
        method: 'getPendingMessagesMetric',
        service: MetricsController.name,
      });

      // Return simple JSON for KEDA metrics-api scaler
      return {
        metricValue: metrics.totalPendingMessages,
      };
    } catch (error) {
      this.logger.error(
        'Failed to get pending messages metric',
        {
          method: 'getPendingMessagesMetric',
          service: MetricsController.name,
        },
        error,
      );

      // Return 0 on error to prevent scaling issues
      return {
        metricValue: 0,
      };
    }
  }

  // Active streams count endpoint (optimized)
  @Get('metrics/active-streams')
  @Header('Content-Type', 'application/json')
  public async getActiveStreamsMetric(
    @Req() request: Request,
  ): Promise<{ activeStreamsCount: number }> {
    try {
      const activeStreamsCount =
        await this.streamMonitor.getActiveStreamCount();

      const userAgent = request.headers['user-agent'] || 'unknown';
      const forwarded = request.headers['x-forwarded-for'] || request.ip;
      // Log request details to identify caller
      this.logger.debug(
        `ð Active streams metric: ${activeStreamsCount} | ` +
          `UA: ${userAgent} | ` +
          `IP: ${forwarded} | ` +
          `Host: ${request.headers.host} | ` +
          `Origin: ${request.headers.origin || 'none'}`,
        {
          method: 'getActiveStreamsMetric',
          service: MetricsController.name,
        },
      );

      return { activeStreamsCount };
    } catch (error) {
      this.logger.error(
        'Failed to get active streams metric',
        { method: 'getActiveStreamsMetric', service: MetricsController.name },
        error,
      );
      return { activeStreamsCount: 0 };
    }
  }
}

