  }

  public get plantHierarchyApiAppId(): string {
    return this.configService.get<string>('plantHierarchyApiAppId') ?? '';
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private checkConfiguration(): void {
    this.context.method = 'checkConfiguration';
    // List of required configurations
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'plantHierarchyApiAppId', value: this.plantHierarchyApiAppId },
      { key: 'bindingShiftTracking', value: this.bindingShiftTracking },
      {
        key: 'bindingShiftTrackingStatus',
        value: this.bindingShiftTrackingStatus,
      },
    ];

    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          this.context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.log(
      'All required configurations are properly set',
      this.context,
    );
  }
}

