@Injectable()
export class LoggerConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
  ) {}

  public async shipDiLogLevel(): Promise<LogLevel> {
    let value = this.configService.get<string>('shipDiLogLevel') as LogLevel;

    if (value) {
      Logger.warn(`'shipDiLogLevel' was read from environment variable`);
    } else {
      value = (await this.appConfigService.getConfigurationValue(
        'SHIP_DI_LOG_LEVEL',
      )) as LogLevel;
    }

    return value ?? '';
  }

  public async onModuleInit(): Promise<void> {
