import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { TransferByContainerResponseDto } from './dto/transfer-by-container-ids-response.dto';
import { TransferByIdsResponseDto } from './dto/transfer-by-ids-response.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { CreateTransferDto } from '@/modules/transfer/dto/create-transfer.dto';
import { Transfer } from '@/modules/transfer/entities/transfer.entity';

@Injectable()
export class TransferService {
  private readonly logger = new AppLogger(TransferService.name);

  public constructor(
    // Inject the repository for Container entity
    @InjectRepository(Transfer)
    private readonly transferRepo: Repository<Transfer>,
  ) {}

  public async create(transfer: CreateTransferDto): Promise<void> {
    await this.transferRepo.insert(transfer);
  }

  public findAll(): Promise<Array<Transfer>> {
    return this.transferRepo.find();
  }

  public async findTransferById(
    transferIdList: Array<number>,
    plant: number,
  ): Promise<Record<number, TransferByIdsResponseDto>> {
    const result: Record<number, TransferByIdsResponseDto> = {};
    try {
      const transfers = await this.transferRepo.find({
        select: [
          'transferId',
          'containerId',
          'destinationLocation',
          'createdOn',
        ],

        where: {
          plant,
          transferId: In(transferIdList),
        },
      });
      if (transfers) {
        for (const transfer of transfers) {
          const { transferId, ...data } = transfer;
          result[transferId] = { transferId, ...data };
        }
        return result;
      }
      return result;
    } catch (error) {
      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          `Failed to retrieve tansfer [plant: ${plant}]: ${error.message}`,
        );
      }
      return result;
    }
  }

  public async findTransferDetailsByContainers(
    containerIdList: Array<string>,
    plant: number,
  ): Promise<Record<string, TransferByContainerResponseDto>> {
    const result: Record<string, TransferByContainerResponseDto> = {};
    try {
      const query = `DECLARE @containerId NVARCHAR(MAX) = @1;
WITH ids AS (
    SELECT value AS id
    FROM STRING_SPLIT(@containerId, ',')
  )
SELECT
    t.destination_location AS destinationLocation,
    t.created_on          AS createdOn,
    t.container_id        AS containerId
FROM ids AS c
CROSS APPLY (
    SELECT TOP (1)
        t.destination_location,
        t.created_on,
        t.container_id
    FROM transfer AS t
    WHERE t.plant = @0
      AND t.transfer_closed = 1
      AND t.container_id = c.id
    ORDER BY t.transfer_id DESC
) AS t;
`;
      const transfers = await this.transferRepo.query(query, [
        plant,
        containerIdList.join(','),
      ]);
      if (transfers.length >= 0) {
        for (const transfer of transfers) {
          result[transfer.containerId] = {
            createdOn: transfer.createdOn,
            destinationLocation: transfer.destinationLocation,
          };
        }
        return result;
      }
      return result;
    } catch (error) {
      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          `Failed to retrieve tansfer by container id list [plant: ${plant}]: ${error.message}`,
        );
      }
      return result;
    }
  }
}

import { DatabaseType } from 'typeorm';
import { MssqlConfigurationService } from '@/config/database/mssql/abstract.mssql.config.service';
/**
 *
 * @param mssqlConfigService
 */
interface ConnectionOptions {
  encrypt: boolean;
}

interface ConnectionExtra {
  trustServerCertificate: boolean;
  authentication?: {
    type: string;
    options: {
      clientId: string;
    };
  };
}

interface BaseProperties {
  type: DatabaseType;
  host: string;
  port: number;
  database: string;
  options: ConnectionOptions;
  synchronize: boolean;
  lazy: boolean;
  autoLoadEntities: boolean;
  extra: ConnectionExtra;
  entities: Array<string>;
  migrations: Array<string>;
  migrationsTableName: string;
  requestTimeout: number;
}

interface ManagedIdentityProperties extends BaseProperties {
  extra: ConnectionExtra & {
    authentication: {
      type: string;
      options: {
        clientId: string;
      };
    };
  };
}

interface SqlAuthProperties extends BaseProperties {
  username: string;
  password: string;
}

type ConnectionProperties = ManagedIdentityProperties | SqlAuthProperties;
/**
 *
 * @param mssqlConfigService - The configuration service containing MSSQL settings.
 * @returns The connection properties for the database.
 */
export function getDatabaseConnectionProperties(
  mssqlConfigService: MssqlConfigurationService,
): ConnectionProperties {
  const baseProperties: BaseProperties = {
    autoLoadEntities: true,
    database: mssqlConfigService.database,
    entities: mssqlConfigService.entities,
    extra: {
      trustServerCertificate: true,
    },
    host: mssqlConfigService.host,
    lazy: true,
    migrations: mssqlConfigService.migrations,
    migrationsTableName: mssqlConfigService.migrationsTableName,
    options: {
      encrypt: mssqlConfigService.encrypt,
    },
    port: mssqlConfigService.port,
    requestTimeout: mssqlConfigService.requestTimeout,
    synchronize: mssqlConfigService.synchronize,
    type: mssqlConfigService.type as DatabaseType,
  };

  if (mssqlConfigService.useManagedIdentity) {
    const managedIdentityProperties: ManagedIdentityProperties = {
      ...baseProperties,
      extra: {
        ...baseProperties.extra,
        authentication: {
          options: {
            clientId: mssqlConfigService.managedIdentityClientId,
          },
          type: 'azure-active-directory-msi-vm',
        },
      },
    };

    return managedIdentityProperties;
  }

  const sqlAuthProperties: SqlAuthProperties = {
    ...baseProperties,
    password: mssqlConfigService.password,
    username: mssqlConfigService.username,
  };

  return sqlAuthProperties;
}

import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';

export class MssqlDatabaseChecker {
  public constructor(
    @InjectDataSource()
    private dataSource: DataSource,
  ) {}

  public async pendingMigrations(): Promise<boolean> {
    if (!this.dataSource.isInitialized) {
      this.dataSource = await this.dataSource.initialize();
    }

    return this.dataSource.showMigrations();
  }

  public async waitForMigrations(
    logger: AppLogger,
    waitDelayMilliseconds: number,
    remainingRetries: number,
  ): Promise<void> {
    const isPendingMigrations: boolean = await this.pendingMigrations();
    if (isPendingMigrations && remainingRetries > 0) {
      logger.warn(
        `Waiting for Migrations to be applied (delay: ${waitDelayMilliseconds} ms, remainingRetries: ${remainingRetries})`,
      );

      await new Promise((resolve) => {
        setTimeout(resolve, waitDelayMilliseconds);
      });

      await this.waitForMigrations(
        logger,
        waitDelayMilliseconds,
        remainingRetries - 1,
      );
    } else if (remainingRetries <= 0) {
      throw new Error(`Waiting for migrations timed-out`);
    } else {
      logger.log('Migrations applied [OK]');
    }
  }
}

