    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'EventhubSdkConfigService',
    };

    // Required configurations for managed identity authentication
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'transferEventHubName', value: this.eventHubName },
      { key: 'transferEventHubNamespace', value: this.eventHubNamespace },
      { key: 'transferStorageAccountName', value: this.storageAccountName },
      { key: 'transferCheckpointInterval', value: this.checkpointInterval },
