@Injectable()
export class PlantService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(PlantService.name);

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async getSidByPlant(plant: number): Promise<string> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/getPlantById/${plant}`;

    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      const response = (await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
        undefined,
        options,
      )) as Plant | Array<Plant>;

      if (Array.isArray(response)) {
        return response.length > 0 && response[0].sid ? response[0].sid : '';
      }
      return response.sid ?? '';
    } catch (error) {
      console.error('Error invoking Dapr service Production API:', error);
      return '';
    }
  }

  public async getUapIdsByPlant(plantId: number): Promise<Array<Uap>> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `uap/getUapIdsByPlant/${plantId}`;

    try {
      return (await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      )) as Array<Uap>;
    } catch (error) {
      this.logger.error('Error getting UAP IDs by plant:', error);
      return [];
    }
  }

  public async getWorkcenters(
    plantKey: number,
    uap?: string,
    productionLine?: string,
  ): Promise<Array<WorkcenterResultDTO>> {
    const daprClient = new DaprClient(); // Initialize DaprClient
    try {
      // Construct query parameters dynamically
      let queryParameters = `plant=${plantKey}`;

      if (uap) {
        queryParameters += `&uap=${uap}`;
      }

      if (productionLine) {
        queryParameters += `&prodLine=${productionLine}`;
      }

      // Make the GET request to your service using Dapr's invoker
      const response = (await daprClient.invoker.invoke(
        this.daprConfigService.plantHierarchyApiAppId, // Dapr app ID for your service
        `workcenter?${queryParameters}`, // Your API endpoint with query parameters
        HttpMethod.GET, // HTTP GET request
      )) as Array<WorkcenterResultDTO>;

      // Ensure the response is an array and return it
      return Array.isArray(response) ? response : [];
    } catch (error) {
      console.error('Error invoking Dapr service Workcenter API:', error);
      return []; // Return an empty array in case of an error
    }
  }

  public async getResources(
    plantKey: number,
    uap?: string,
    productionLine?: string,
