      if (uap) {
        queryParameters += `&uap=${uap}`;
      }

      if (productionLine) {
        queryParameters += `&prodLine=${productionLine}`;
      }

      if (workcenter) {
        queryParameters += `&workcenter=${workcenter}`;
      }

      // Make the GET request to your service using Dapr's invoker
      const response = (await daprClient.invoker.invoke(
        this.daprConfigService.plantHierarchyApiAppId, // Dapr app ID for your service
        `resource?${queryParameters}`, // Your API endpoint with query parameters
        HttpMethod.GET, // HTTP GET request
      )) as Array<ResourceDTO>;

      // Ensure the response is an array and return it
      return Array.isArray(response) ? response : [];
    } catch (error) {
      console.error('Error invoking Dapr service Resource API:', error);
      return []; // Return an empty array in case of an error
    }
  }

  public async getProdlines(
    plantKey: number,
    uap?: string,
  ): Promise<Array<ProductionLineDto>> {
    const daprClient = new DaprClient(); // Initialize DaprClient
    try {
      // Construct query parameters dynamically
      let queryParameters = `plant=${plantKey}`;

      if (uap) {
        queryParameters += `&uap=${uap}`;
      }

      // Make the GET request to your service using Dapr's invoker
      const response = (await daprClient.invoker.invoke(
        this.daprConfigService.plantHierarchyApiAppId, // Dapr app ID for your service
        `prodline?${queryParameters}`, // Your API endpoint with query parameters
        HttpMethod.GET, // HTTP GET request
      )) as Array<ProductionLineDto>;

      // Ensure the response is an array and return it
      return Array.isArray(response) ? response : [];
    } catch (error) {
      this.logger.error(
        'Error invoking Dapr service ProductionLine API:',
        error,
      );
      return []; // Return an empty array in case of an error
    }
  }

  public async getPlant(): Promise<Array<string>> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethodPlant = `plant`;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const response = await this.daprClient.invoker
      .invoke(
        serviceAppId,
        serviceMethodPlant,
        HttpMethod.GET,
        undefined,
        options,
      )
      .catch((error: Error) => {
        this.logger.error(error);
        throw new Error('Error fetching plant data');
