import { Injectable, Logger } from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';
import { DaprConfigService } from 'src/config/dapr/dapr-config.service';
import { UserPreferenceDto } from './dtos/user-preference.dto';

@Injectable()
export class UserPreferenceService {
  private readonly daprClient: DaprClient;

  private readonly serviceAppId: string;

  private readonly logger = new Logger(UserPreferenceService.name);

  private readonly authorizationHeaderKey = 'Authorization';

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
    this.serviceAppId = this.daprConfigService.umeApiAppId;
  }

  public async getPreferences(
    plant: number,
    userId: number | string,
    appName: string,
  ): Promise<Array<UserPreferenceDto>> {
    try {
      const safeAppName = encodeURIComponent(appName);

      const token = process.env.TOKEN;
      const options = token
        ? {
            headers: {
              [this.authorizationHeaderKey]: `Bearer ${token}`,
            },
          }
        : undefined;

      const response = await this.daprClient.invoker.invoke(
        this.serviceAppId,
        `user-preference/${plant}/${userId}/${safeAppName}`,
        HttpMethod.GET,
        undefined,
        options,
      );

      return Array.isArray(response)
        ? (response as Array<UserPreferenceDto>)
        : [];
    } catch (error) {
      this.logger.error('Error fetching user preferences:', error);
      return [];
    }
  }

  public async savePreferences(
    preferences: Array<UserPreferenceDto>,
  ): Promise<string> {
    try {
      const token = process.env.TOKEN;
      const options = token
        ? {
            headers: {
              [this.authorizationHeaderKey]: `Bearer ${token}`,
            },
          }
        : undefined;

      const response = await this.daprClient.invoker.invoke(
        this.serviceAppId,
        'user-preference/save',
        HttpMethod.POST,
        preferences,
        options,
      );

      return typeof response === 'string'
        ? response
        : 'User preferences inserted successfully';
    } catch (error) {
      this.logger.error('Error saving user preferences:', error);
      throw error;
    }
  }
}

