  public async getWKOrdersByKPIName(
    plantId: number,
    kpiName: string,
  ): Promise<Array<Buffer>> {
    const { urlOrderApi } = this.urlApiConfigService;
    const serviceMethodOrder = `/buffer/getWKOrdersByKPIName/${plantId}/${kpiName}`;

    try {
      const response = await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethodOrder,
        HttpMethod.GET,
