/**
 * Formats the given departure time string by extracting the date and time parts
 * and concatenating them with a space in between.
 * @param departureTime - The departure time string in the format 'YYYY-MM-DDTHH:mm:ss'.
 * @returns The formatted departure time string in the format 'YYYY-MM-DD HH:mm:ss',
 *          or an empty string if the departure time is undefined.
 */
export function formatDepartureOrPickingTime(
  departureTime: string | undefined,
): string {
  // Check if WKDetail and departureTime are available
  if (departureTime) {
    // Extract date and time parts from departureTime
    const datePart = departureTime.slice(0, 10);
    const timePart = departureTime.slice(11, 19);

    // Concatenate date and time parts with a space in between
    return `${datePart} ${timePart}`;
  }
  return '';
}

